// Pure helpers for the tests lab (no React): same maths as scripts/spatial_tests.py and the period/region analysis.

// weighted quantile: first sorted value whose cumulative weight reaches q of the total
export function wq(v, w, q) {
  const o = Array.from(v.keys()).sort((a, b) => v[a] - v[b]);
  let tot = 0;
  for (const i of o) tot += w[i];
  const target = tot * q;
  let cw = 0;
  for (const i of o) { cw += w[i]; if (cw >= target) return v[i]; }
  return v[o[o.length - 1]];
}

// effective radius (km) and elongation of the core of a weighted point set
// Azimuthal equidistant projection about (lat0, lon0): km east and north, and back. Used for ovals that span an ocean,
// where a flat plane scaled to one latitude bends the long axis. Directions from the centre are true bearings.
const R_KM = 6371, D2R = Math.PI / 180;
export function azFwd(lat0, lon0, la, lo) {
  const p0 = lat0 * D2R, p = la * D2R, dl = (lo - lon0) * D2R;
  const c = Math.acos(Math.min(1, Math.max(-1, Math.sin(p0) * Math.sin(p) + Math.cos(p0) * Math.cos(p) * Math.cos(dl))));
  const k = c < 1e-9 ? R_KM : (c / Math.sin(c)) * R_KM;
  return [k * Math.cos(p) * Math.sin(dl), k * (Math.cos(p0) * Math.sin(p) - Math.sin(p0) * Math.cos(p) * Math.cos(dl))];
}
export function azInv(lat0, lon0, e, n) {
  const r = Math.hypot(e, n);
  if (r < 1e-9) return [lat0, lon0];
  const p0 = lat0 * D2R, c = r / R_KM;
  const lat = Math.asin(Math.cos(c) * Math.sin(p0) + (n * Math.sin(c) * Math.cos(p0)) / r);
  const lon = lon0 * D2R + Math.atan2(e * Math.sin(c), r * Math.cos(p0) * Math.cos(c) - n * Math.sin(p0) * Math.sin(c));
  return [lat / D2R, ((lon / D2R + 540) % 360) - 180];
}

// effective radius (km) and elongation of the core of a weighted point set. az = true fits on the azimuthal equidistant plane.
export function spread(lat, lon, w, az = false) {
  if (az === 'auto') { const s0 = spread(lat, lon, w, false); return s0 && s0.ra > 2000 ? spread(lat, lon, w, true) : s0; } // very long ovals are refitted on the equidistant plane
  const n = lat.length;
  const lat0 = wq(lat, w, 0.5), lon0 = wq(lon, w, 0.5);
  const k = Math.cos((lat0 * Math.PI) / 180) * 111.32;
  const x = new Array(n), y = new Array(n), r = new Array(n);
  for (let i = 0; i < n; i++) {
    if (az) { const q = azFwd(lat0, lon0, lat[i], lon[i]); x[i] = q[0]; y[i] = q[1]; } else { x[i] = (lon[i] - lon0) * k; y[i] = (lat[i] - lat0) * 110.57; }
    r[i] = Math.hypot(x[i], y[i]);
  }
  const thr = Math.max(wq(r, w, 0.85), 1e-6);
  const core = [];
  for (let i = 0; i < n; i++) if (r[i] <= thr) core.push(i);
  if (core.length < 3) return null;
  const moments = (xs, ys) => {
    let sw = 0, mx = 0, my = 0;
    for (const i of core) { sw += w[i]; mx += w[i] * xs[i]; my += w[i] * ys[i]; }
    mx /= sw; my /= sw;
    let a = 0, b = 0, c = 0;
    for (const i of core) { const dx = xs[i] - mx, dy = ys[i] - my; a += w[i] * dx * dx; b += w[i] * dx * dy; c += w[i] * dy * dy; }
    return { mx, my, a: a / sw, b: b / sw, c: c / sw };
  };
  let M = moments(x, y), latC = lat0 + M.my / 110.57, lonC = lon0 + M.mx / k;
  if (az) {
    // centre the projection on the oval's own centre so the axis angle is a true bearing there
    [latC, lonC] = azInv(lat0, lon0, M.mx, M.my);
    const x2 = new Array(n), y2 = new Array(n);
    for (let i = 0; i < n; i++) { const q = azFwd(latC, lonC, lat[i], lon[i]); x2[i] = q[0]; y2[i] = q[1]; }
    M = moments(x2, y2);
  }
  const { a, b, c } = M;
  const m = (a + c) / 2, d = Math.sqrt(((a - c) / 2) ** 2 + b * b);
  const e0 = Math.max(m - d, 1), e1 = Math.max(m + d, 1);
  const theta = (0.5 * Math.atan2(2 * b, a - c) * 180) / Math.PI; // major-axis angle, degrees counter-clockwise from east
  return { radius: Math.sqrt(Math.sqrt(e0 * e1)), elong: Math.sqrt(e1 / e0), lat0, lon0, latC, lonC, ra: Math.sqrt(e1), rb: Math.sqrt(e0), theta, circ: Math.sqrt((e0 + e1) / 2), az };
}

// k distinct indices out of n (partial Fisher-Yates)
export function sampleIdx(n, k, rnd = Math.random) {
  const a = new Uint32Array(n);
  for (let i = 0; i < n; i++) a[i] = i;
  for (let i = 0; i < k; i++) {
    const j = i + Math.floor(rnd() * (n - i));
    const t = a[i]; a[i] = a[j]; a[j] = t;
  }
  return Array.from(a.slice(0, k));
}

// which rows survive each place set: 0 all places, 1 no generic "Ukraine" places, 2 also no region centroids
export function keepRow(gen, level) {
  if (level === 0) return true;
  if (level === 1) return gen !== 1;
  return gen === 0;
}

// share of variance between groups for unit-length sparse rows, with optional fractional membership.
// rows: [{terms:[idx], val}], groups: array (per row) of arrays of group ids (weights 1/len)
export function betweenShare(rows, V, groups, nGroups) {
  const N = rows.length;
  const S = Array.from({ length: nGroups }, () => new Float64Array(V));
  const W = new Float64Array(nGroups);
  const tot = new Float64Array(V);
  for (let i = 0; i < N; i++) {
    const { terms, val } = rows[i];
    const gs = groups[i], wt = 1 / gs.length;
    for (const t of terms) tot[t] += val;
    for (const g of gs) {
      W[g] += wt;
      const s = S[g];
      for (const t of terms) s[t] += val * wt;
    }
  }
  let sumTot = 0;
  for (let t = 0; t < V; t++) sumTot += tot[t] * tot[t];
  let between = 0;
  for (let g = 0; g < nGroups; g++) {
    if (W[g] === 0) continue;
    let s2 = 0;
    const s = S[g];
    for (let t = 0; t < V; t++) s2 += s[t] * s[t];
    between += s2 / W[g];
  }
  between -= sumTot / N;
  const total = N - sumTot / N;
  return between / total;
}

export function shuffled(arr, rnd = Math.random) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rnd() * (i + 1));
    const t = a[i]; a[i] = a[j]; a[j] = t;
  }
  return a;
}

export function buildRows(spec) {
  return spec.rows.map(([e, regs, terms]) => ({ terms, val: 1 / Math.sqrt(terms.length), era: e, regs }));
}

export function percentile(sorted, p) {
  if (!sorted.length) return NaN;
  const i = Math.min(sorted.length - 1, Math.max(0, Math.round(p * (sorted.length - 1))));
  return sorted[i];
}
