import React, { useEffect, useMemo, useState } from 'react';

// A searchable list of every catalog record with the reason it is or is not
// used in the delay charts. Data: public/data/lag_all.json
// [id, title, pubYear (0 = none), [bandIdx], [languages], status, periodStart, periodEnd]

const STATUS = [
  'Used', 'Used (period read from the title)', 'No publication year', 'No subject dates at all',
  'Subject heading has no date', 'Open-ended period', 'Period runs past publication', 'Usable period, but no topic theme',
];
const PAGE = 100;

export default function RecordBrowser({ all: allProp }) {
  const [open, setOpen] = useState(false);
  const [fetched, setFetched] = useState(null);
  const [q, setQ] = useState('');
  const [lang, setLang] = useState('');
  const [status, setStatus] = useState('');
  const [limit, setLimit] = useState(PAGE);
  const all = allProp || fetched;

  useEffect(() => {
    if (!open || all) return undefined;
    let cancelled = false;
    fetch(`${process.env.PUBLIC_URL}/data/lag_all.json`)
      .then((r) => r.json())
      .then((d) => { if (!cancelled) setFetched(d); })
      .catch((e) => console.error('Failed to load lag_all.json', e));
    return () => { cancelled = true; };
  }, [open, all]);

  const langs = useMemo(() => {
    if (!all) return [];
    const c = {};
    for (const r of all.records) for (const l of r[4]) c[l] = (c[l] || 0) + 1;
    return Object.entries(c).sort((a, b) => b[1] - a[1]).slice(0, 12);
  }, [all]);

  const counts = useMemo(() => {
    const c = {};
    if (all) for (const r of all.records) c[r[5]] = (c[r[5]] || 0) + 1;
    return c;
  }, [all]);

  const list = useMemo(() => {
    if (!all) return [];
    const needle = q.trim().toLowerCase();
    return all.records.filter((r) => {
      if (status !== '' && r[5] !== +status) return false;
      if (lang && !r[4].includes(lang)) return false;
      return !needle || r[1].toLowerCase().includes(needle);
    });
  }, [all, q, lang, status]);

  return (
    <details className="lag-funnel" onToggle={(e) => setOpen(e.currentTarget.open)} style={{ maxWidth: 'none' }}>
      <summary>Browse every record{all ? ` (${all.records.length.toLocaleString()})` : ''} and see why it is or is not used</summary>
      {!all ? <p className="lag-muted">Loading…</p> : (
        <>
          <div className="lag-toolbar" style={{ marginTop: 8 }}>
            <label>Search titles
              <input type="search" value={q} placeholder="e.g. Голодомор or Holodomor" onChange={(e) => { setQ(e.target.value); setLimit(PAGE); }}
                style={{ background: 'var(--surface-2)', color: 'var(--text-primary)', border: '1px solid var(--border)', borderRadius: 6, padding: '5px 8px' }} />
            </label>
            <label>Language
              <select value={lang} onChange={(e) => { setLang(e.target.value); setLimit(PAGE); }}>
                <option value="">all</option>
                {langs.map(([l, n]) => <option key={l} value={l}>{l} ({n})</option>)}
              </select>
            </label>
            <label>Status
              <select value={status} onChange={(e) => { setStatus(e.target.value); setLimit(PAGE); }}>
                <option value="">all</option>
                {STATUS.map((t, i) => <option key={t} value={i}>{t} ({(counts[i] || 0).toLocaleString()})</option>)}
              </select>
            </label>
          </div>
          <p className="lag-muted">{list.length.toLocaleString()} record{list.length === 1 ? '' : 's'} match.</p>
          <div style={{ overflowX: 'auto' }}>
            <table className="lag-table">
              <thead><tr><th>Title</th><th>Published</th><th>Language</th><th>Period</th><th>Status</th></tr></thead>
              <tbody>
                {list.slice(0, limit).map((r) => (
                  <tr key={r[0]}>
                    <td>{r[1]}</td>
                    <td>{r[2] || '—'}</td>
                    <td>{r[4].join(', ') || '—'}</td>
                    <td>{r[7] ? (r[6] === r[7] ? r[6] : `${r[6]}–${r[7]}`) : '—'}</td>
                    <td className="lag-muted">{STATUS[r[5]]}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {limit < list.length && (
            <button className="lag-more" onClick={() => setLimit(limit + PAGE * 2)}>
              Show {Math.min(PAGE * 2, list.length - limit)} more
            </button>
          )}
        </>
      )}
    </details>
  );
}
