import React, { useEffect, useMemo, useState } from 'react';
import * as d3 from 'd3';
import './Lag.css';
import CoverageFunnel from './CoverageFunnel';
import RecordBrowser from './RecordBrowser';

// Publication delay by topic: how many years after the period a book covers
// did the book itself appear? Data comes from public/data/lag_data.json,
// built by scripts/make_lag_data.py (only records with a real dated subject
// period -- see the methodology note on the page).

const W = 1000;
const ROW_H = 28;
const M = { top: 30, right: 70, bottom: 36, left: 290 };

function quantile(sorted, p) {
  return d3.quantileSorted(sorted, p);
}

export default function Lag() {
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);
  const [ref, setRef] = useState('end'); // 'end' | 'mid'
  const [maxSpan, setMaxSpan] = useState(100);
  const [minN, setMinN] = useState(10);
  const [useTitles, setUseTitles] = useState(false);
  const [useOpen, setUseOpen] = useState(false);
  const [selected, setSelected] = useState(null); // band index
  const [showAll, setShowAll] = useState(false);

  useEffect(() => {
    let cancelled = false;
    fetch(`${process.env.PUBLIC_URL}/data/lag_data.json`)
      .then((r) => r.json())
      .then((d) => { if (!cancelled) setData(d); })
      .catch((e) => { console.error('Failed to load lag_data.json', e); if (!cancelled) setError(e); });
    return () => { cancelled = true; };
  }, []);

  // Per-record lag under the current settings.
  const rows = useMemo(() => {
    if (!data) return [];
    const out = [];
    for (const [id, title, pubY, s, e, bands, src] of data.records) {
      if (src === 1 && !useTitles) continue;
      if (src === 2 && !useOpen) continue;
      if (src !== 2 && e - s > maxSpan) continue;
      // open-ended periods: only the start is meaningful, so the delay is a maximum
      const ev = src === 2 ? s : ref === 'mid' ? (s + e) / 2 : e;
      const lag = pubY - ev;
      if (lag < 0) continue;
      out.push({ id, title, pubY, s, e, lag, bands, src });
    }
    return out;
  }, [data, ref, maxSpan, useTitles, useOpen]);

  // Per-topic stats.
  const stats = useMemo(() => {
    if (!data) return [];
    const by = data.bandOrder.map(() => []);
    for (const r of rows) for (const b of r.bands) by[b].push(r.lag);
    const list = [];
    by.forEach((lags, bi) => {
      if (!lags.length) return;
      lags.sort((a, b) => a - b);
      list.push({
        bi,
        key: data.bandOrder[bi],
        label: data.bandLabel[data.bandOrder[bi]] || data.bandOrder[bi],
        color: data.bandColor[data.bandOrder[bi]] || '#888',
        n: lags.length,
        p10: quantile(lags, 0.1),
        q1: quantile(lags, 0.25),
        med: quantile(lags, 0.5),
        q3: quantile(lags, 0.75),
        p90: quantile(lags, 0.9),
        lags,
      });
    });
    list.sort((a, b) => a.med - b.med);
    return list;
  }, [data, rows]);

  const shown = stats.filter((s) => s.n >= minN);
  const hidden = stats.length - shown.length;
  const overall = useMemo(() => {
    if (!rows.length) return null;
    const l = rows.map((r) => r.lag).sort((a, b) => a - b);
    return { n: l.length, med: quantile(l, 0.5) };
  }, [rows]);

  const sel = shown.find((s) => s.bi === selected) || null;
  const nTitleRecs = data ? data.records.filter((r) => r[6] === 1).length : 0;
  const nOpenRecs = data ? data.records.filter((r) => r[6] === 2).length : 0;
  const nUsable = data ? data.records.length - (useTitles ? 0 : nTitleRecs) - (useOpen ? 0 : nOpenRecs) : 0;

  if (error) return <div className="lag-root"><p>Could not load the lag data.</p></div>;
  if (!data) return <div className="lag-root"><p className="lag-muted">Loading…</p></div>;

  const H = M.top + M.bottom + ROW_H * shown.length;
  const xMax = d3.max(shown, (s) => s.p90) || 100;
  const x = d3.scaleSymlog().constant(15).domain([0, xMax]).range([M.left, W - M.right]).nice();
  const ticks = [0, 5, 10, 25, 50, 100, 250, 500, 1000, 2000].filter((t) => t <= x.domain()[1]);

  return (
    <div className="lag-root">
      <h1>Publication delay by topic</h1>
      <div className="lag-links">
        <a href="#/">← About this project</a>
        <a href="#/lag-languages">Delay by language →</a>
        <a href="#/topics">Subject themes river →</a>
        <a href="#/map">Map &amp; network explorer →</a>
        <a href="#/influence">Russia &amp; Poland river →</a>
      </div>
      <p className="lag-subtitle">
        How many years after the period a book covers does the book itself appear? Each bar shows,
        for one topic, the middle half of that delay (box), the median (white tick) and the 10th–90th
        percentile range (whiskers). Topics are sorted from fastest to slowest to be written about.
        {overall && <> Across all {overall.n.toLocaleString()} qualifying records the median delay is{' '}
        <b>{Math.round(overall.med)} years</b>.</>}
      </p>

      <div className="lag-method">
        <b>What is measured:</b> delay = publication year − the end (or midpoint) of the period named
        by a subject heading's date subdivision, e.g. “19th century” or “1648–1775”. Only
        {' '}{nUsable.toLocaleString()} of the {data.totalRecords.toLocaleString()} records in the
        catalog can be used: records whose heading has no date, or whose period runs open-ended up to
        the publication year, are left out because they say nothing about delay. This makes the sample
        small and skewed toward dated historical topics, so treat topics with few records as
        indicative only. A record can count toward more than one topic. The horizontal axis is
        compressed (symmetric log) so that fast-moving topics and Antiquities can share one chart.
        <br /><br />
        <b>Dates found in titles:</b> the option below adds {nTitleRecs} records whose subject headings
        carry no usable period but whose <i>title</i> contains a year range (“…, 1918–1953”) or a
        century (“XVII veka”, “18th century”). Single years are ignored, since they are often yearbooks
        or conference years, and BC periods are skipped. Dates in parentheses after a person's name
        are life dates, so for biographies the delay runs from death, not from the events of a career.
      </div>

      <CoverageFunnel data={data} titleExtra={nTitleRecs} useTitles={useTitles} openExtra={nOpenRecs} useOpen={useOpen} />

      <div className="lag-toolbar">
        <label>
          Measure from the
          <select value={ref} onChange={(e) => setRef(e.target.value)}>
            <option value="end">end of the period covered</option>
            <option value="mid">midpoint of the period covered</option>
          </select>
        </label>
        <label>
          Ignore periods wider than
          <input type="range" min="10" max="300" step="10" value={maxSpan}
                 onChange={(e) => setMaxSpan(+e.target.value)} />
          <b>{maxSpan} yrs</b>
        </label>
        <label title="Adds records whose period is open-ended (&quot;1991-&quot;) or runs past the publication year. Their delay is measured from the start of the period, so it is a maximum.">
          <input type="checkbox" checked={useOpen} onChange={(e) => setUseOpen(e.target.checked)} />
          Include open-ended periods
          <b>(+{nOpenRecs} records, delay = maximum)</b>
        </label>
        <label title="Adds records whose title contains a year range or a century, when their subject headings have no usable period">
          <input type="checkbox" checked={useTitles} onChange={(e) => setUseTitles(e.target.checked)} />
          Also use dates found in titles
          <b>(+{nTitleRecs} records)</b>
        </label>
        <label>
          Hide topics with fewer than
          <input type="range" min="1" max="60" step="1" value={minN}
                 onChange={(e) => setMinN(+e.target.value)} />
          <b>{minN} records</b>
        </label>
      </div>

      <svg className="lag-chart" viewBox={`0 0 ${W} ${H}`} role="img"
           aria-label="Box plot of publication delay in years for each topic">
        {ticks.map((t) => (
          <g key={t}>
            <line className="lag-grid" x1={x(t)} x2={x(t)} y1={M.top - 6} y2={H - M.bottom} />
            <text className="lag-tick" x={x(t)} y={H - M.bottom + 16} textAnchor="middle">{t}</text>
          </g>
        ))}
        <text className="lag-axis-title" x={(M.left + W - M.right) / 2} y={H - 4} textAnchor="middle">
          years between the period covered and publication
        </text>
        {shown.map((s, i) => {
          const y = M.top + i * ROW_H;
          const cy = y + ROW_H / 2;
          const active = selected === s.bi;
          return (
            <g key={s.key} className={'lag-row' + (active ? ' active' : '')}
               onClick={() => setSelected(active ? null : s.bi)} style={{ cursor: 'pointer' }}>
              <title>{`${s.label}: median ${Math.round(s.med)} yrs, middle half ${Math.round(s.q1)}–${Math.round(s.q3)} yrs, n=${s.n}`}</title>
              <rect x={0} y={y} width={W} height={ROW_H} className="lag-row-bg" />
              <text className="lag-label" x={M.left - 12} y={cy + 4} textAnchor="end">{s.label}</text>
              <line className="lag-whisker" x1={x(s.p10)} x2={x(s.p90)} y1={cy} y2={cy} stroke={s.color} />
              <rect x={x(s.q1)} y={cy - 8} width={Math.max(2, x(s.q3) - x(s.q1))} height={16} rx={3}
                    fill={s.color} opacity={active ? 1 : 0.85} />
              <line className="lag-median" x1={x(s.med)} x2={x(s.med)} y1={cy - 8} y2={cy + 8} />
              <text className="lag-n" x={W - M.right + 10} y={cy + 4}>n={s.n}</text>
            </g>
          );
        })}
      </svg>
      {hidden > 0 && (
        <p className="lag-muted">
          {hidden} topic{hidden > 1 ? 's' : ''} hidden because of too few records; lower the
          threshold above to show {hidden > 1 ? 'them' : 'it'}.
        </p>
      )}

      {sel ? (
        <Detail sel={sel} rows={rows} showAll={showAll} setShowAll={setShowAll} onClose={() => setSelected(null)} />
      ) : (
        <p className="lag-muted">Click a topic to see its distribution and the books behind it.</p>
      )}
      <RecordBrowser />
    </div>
  );
}

function Detail({ sel, rows, showAll, setShowAll, onClose }) {
  const recs = useMemo(
    () => rows.filter((r) => r.bands.includes(sel.bi)).sort((a, b) => b.lag - a.lag),
    [rows, sel.bi]
  );

  const w = 1000, h = 190, m = { t: 12, r: 20, b: 30, l: 40 };
  const cap = Math.max(100, Math.ceil(d3.quantileSorted(sel.lags, 0.95) / 10) * 10);
  const bins = d3.bin().domain([0, cap]).thresholds(d3.range(0, cap, cap > 150 ? 20 : 5))(
    sel.lags.map((v) => Math.min(v, cap - 0.001))
  );
  const hx = d3.scaleLinear().domain([0, cap]).range([m.l, w - m.r]);
  const hy = d3.scaleLinear().domain([0, d3.max(bins, (b) => b.length) || 1]).nice().range([h - m.b, m.t]);
  const over = sel.lags.filter((v) => v >= cap).length;

  const list = showAll ? recs : recs.slice(0, 15);

  return (
    <div className="lag-detail">
      <div className="lag-detail-head">
        <h2><span className="lag-swatch" style={{ background: sel.color }} />{sel.label}</h2>
        <button type="button" onClick={onClose}>Close</button>
      </div>
      <p className="lag-subtitle">
        {sel.n} records · median delay <b>{Math.round(sel.med)} years</b> · middle half{' '}
        {Math.round(sel.q1)}–{Math.round(sel.q3)} years · 90% within {Math.round(sel.p90)} years.
      </p>
      <svg className="lag-chart" viewBox={`0 0 ${w} ${h}`} role="img"
           aria-label={`Histogram of publication delay for ${sel.label}`}>
        {hy.ticks(4).map((t) => (
          <g key={t}>
            <line className="lag-grid" x1={m.l} x2={w - m.r} y1={hy(t)} y2={hy(t)} />
            <text className="lag-tick" x={m.l - 6} y={hy(t) + 4} textAnchor="end">{t}</text>
          </g>
        ))}
        {bins.map((b, i) => (
          <rect key={i} x={hx(b.x0) + 1} y={hy(b.length)} width={Math.max(1, hx(b.x1) - hx(b.x0) - 2)}
                height={hy(0) - hy(b.length)} fill={sel.color} opacity="0.85" />
        ))}
        <line className="lag-median-line" x1={hx(Math.min(sel.med, cap))} x2={hx(Math.min(sel.med, cap))} y1={m.t} y2={h - m.b} />
        {hx.ticks(8).map((t) => (
          <text key={t} className="lag-tick" x={hx(t)} y={h - m.b + 16} textAnchor="middle">{t}</text>
        ))}
        <text className="lag-axis-title" x={(m.l + w - m.r) / 2} y={h - 2} textAnchor="middle">
          years of delay{over ? ` (last bin includes ${over} longer)` : ''}
        </text>
      </svg>

      <table className="lag-table">
        <thead>
          <tr><th>Title</th><th>Period covered</th><th>Published</th><th>Delay</th></tr>
        </thead>
        <tbody>
          {list.map((r) => (
            <tr key={r.id}>
              <td>{r.title.replace(/\s*[/:]\s*$/, '')}</td>
              <td>{r.s === r.e ? r.s : `${r.s}–${r.e}`}{r.src === 1 && <span className="lag-badge" title="This period was read from the title, not the subject headings">from title</span>}{r.src === 2 && <span className="lag-badge" title="Open-ended period: the delay is measured from its start, so it is a maximum">upper bound</span>}</td>
              <td>{r.pubY}</td>
              <td>{Math.round(r.lag)} yrs</td>
            </tr>
          ))}
        </tbody>
      </table>
      {recs.length > 15 && (
        <button type="button" className="lag-more" onClick={() => setShowAll(!showAll)}>
          {showAll ? 'Show fewer' : `Show all ${recs.length} (longest delay first)`}
        </button>
      )}
    </div>
  );
}
