import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import './TestsLab.css';
import { Panel, C } from './TestsLab';
import OvalMap from './OvalMap';

const NA_CITIES = [{ name: 'New York', lat: 40.71, lon: -74.01, color: '#e0a526' }, { name: 'Toronto', lat: 43.65, lon: -79.38, color: '#d96bb0' }];
const LABEL = {
  '<1400': 'Before 1400', '1400-1648': '1400-1648', '1648-1800': '1648-1800', '1800-1917': '1800-1917',
  '1917-45': '1917-45', '1945-91': '1945-91', '1991+': '1991 on',
};

// Regions and eras. Data: public/data/region_ridge.json (kernel densities, over the seven eras, of the
// earliest year of the subject periods of the 1,545 books with an era and a located place, split by region).
const REG = ['west', 'centre', 'east', 'south'];
const REG_COL = { west: '#4aa3df', centre: '#1fb58a', east: '#e0732e', south: '#e8ae2b' };
const ERA_SHORT = ['before 1400', '1400–1648', '1648–1800', '1800–1917', '1917–45', '1945–91', '1991 on'];

function RegionMap({ map, hl, setHl }) {
  const k = Math.cos((48.5 * Math.PI) / 180);
  const x0 = 22 * k, x1 = 40.5 * k, y0 = 44, y1 = 52.5;
  const W = 520, H = Math.round((W * (y1 - y0)) / (x1 - x0));
  const sx = (lon) => ((lon * k - x0) / (x1 - x0)) * W;
  const sy = (lat) => H - ((lat - y0) / (y1 - y0)) * H;
  const ring = (r) => 'M ' + r.map(([la, lo]) => `${sx(lo).toFixed(1)} ${sy(la).toFixed(1)}`).join(' L ') + ' Z';
  const outline = map.outline.map(ring).join(' ');
  const rect = {
    west: [0, 0, sx(26.8), H],
    centre: [sx(26.8), 0, sx(34.5) - sx(26.8), sy(47.3)],
    east: [sx(34.5), 0, W - sx(34.5), sy(47.3)],
    south: [sx(26.8), sy(47.3), W - sx(26.8), H - sy(47.3)],
  };
  const lab = { west: [24.2, 50.0], centre: [30.6, 50.4], east: [37.5, 49.3], south: [33.2, 45.9] };
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="tl-hist" role="img" aria-label="The four regions of the country">
      <defs><clipPath id="regclip"><path d={outline} /></clipPath></defs>
      <g clipPath="url(#regclip)">
        {REG.map((g) => <rect key={g} x={rect[g][0]} y={rect[g][1]} width={rect[g][2]} height={rect[g][3]} fill={REG_COL[g]} opacity={hl && hl !== g ? 0.18 : 0.6} onMouseEnter={() => setHl(g)} onMouseLeave={() => setHl(null)} />)}
      </g>
      {map.outline.map((r, i) => <path key={i} d={ring(r)} fill="none" stroke="#9aa3ae" strokeWidth="1" />)}
      <line x1={sx(26.8)} x2={sx(26.8)} y1={sy(52.4)} y2={sy(48.2)} stroke="#e6e9ee" strokeDasharray="4 4" opacity="0.7" />
      <line x1={sx(34.5)} x2={sx(34.5)} y1={sy(52.4)} y2={sy(44.2)} stroke="#e6e9ee" strokeDasharray="4 4" opacity="0.7" />
      <line x1={sx(26.8)} x2={sx(40.3)} y1={sy(47.3)} y2={sy(47.3)} stroke="#e6e9ee" strokeDasharray="4 4" opacity="0.7" />
      {REG.map((g) => <text key={g} x={sx(lab[g][0])} y={sy(lab[g][1])} textAnchor="middle" className="tl-marklabel" fill="#fff" style={{ pointerEvents: 'none' }}>{g}</text>)}
    </svg>
  );
}

function RegionRidges({ rr, map }) {
  const [hl, setHl] = useState(null);
  const xs = rr.xs;
  const peak = Math.max(...REG.flatMap((g) => rr.dens[g]));
  const Wd = 640, m = { l: 104, r: 14, t: 12, b: 38 };
  const iw = Wd - m.l - m.r;
  const sx = (v) => m.l + (v / 7) * iw;
  const ticks = ERA_SHORT.map((t, i) => <text key={t} x={sx(i + 0.5)} textAnchor="middle" className="tl-tick">{t}</text>);
  // stacked
  const rowH = 78, Hs = m.t + rowH * 4 + m.b + 40;
  const baseS = (i) => m.t + 40 + rowH * (i + 1) - 6;
  const amp = rowH * 1.75;
  const pathS = (ys, b) => `M ${sx(xs[0])} ${b} ` + ys.map((y, k) => `L ${sx(xs[k]).toFixed(1)} ${(b - (y / peak) * amp).toFixed(1)}`).join(' ') + ` L ${sx(xs[xs.length - 1])} ${b} Z`;
  const lineS = (ys, b, h, hs) => ys.map((y, k) => `${k ? 'L' : 'M'} ${sx(xs[k]).toFixed(1)} ${(b - (y / peak) * h).toFixed(1)}`).join(' ');
  // overlay
  const Ho = 300, mo = { l: 14, r: 14, t: 16, b: 38 };
  const sxo = (v) => mo.l + (v / 7) * (Wd - mo.l - mo.r);
  const syo = (v) => Ho - mo.b - (v / peak) * (Ho - mo.b - mo.t);
  const lineO = (ys) => ys.map((y, k) => `${k ? 'L' : 'M'} ${sxo(xs[k]).toFixed(1)} ${syo(y).toFixed(1)}`).join(' ');
  const areaO = (ys) => lineO(ys) + ` L ${sxo(xs[xs.length - 1])} ${syo(0)} L ${sxo(xs[0])} ${syo(0)} Z`;
  return (
    <Panel n="1" title="When are the books about each region about?"
      lead={`The country is divided into four regions by simple boxes (map, left). Each ridge shows when the books about a region are about: the weighted distribution of the earliest year of their subject periods, over the seven eras (each drawn with the same width). A book about places in two regions counts in both, each place weighing 1/k. ${rr.books.toLocaleString()} books have an era and a located place. Point at a region or a ridge to highlight it.`}>
      <div className="tl-row">
        <div className="tl-col" style={{ flex: '1 1 340px', minWidth: 0, maxWidth: 520 }}>
          <h3>How the country is divided into four regions</h3>
          <RegionMap map={map} hl={hl} setHl={setHl} />
          <p className="tl-note">South: south of 47.3°N and east of 26.8°E. West: west of 26.8°E. East: east of 34.5°E. Centre: the rest.</p>
        </div>
        <div className="tl-col" style={{ flex: '1 1 440px', minWidth: 0 }}>
          <h3>One ridge for each region</h3>
          <svg viewBox={`0 0 ${Wd} ${Hs}`} className="tl-hist" role="img" aria-label="Ridges of the era of the books about each region">
            {[1, 2, 3, 4, 5, 6].map((b) => <line key={b} x1={sx(b)} x2={sx(b)} y1={m.t + 22} y2={Hs - m.b} stroke="#7d8794" opacity="0.35" />)}
            {REG.map((g, i) => {
              const b = baseS(i), on = !hl || hl === g;
              return (
                <g key={g} onMouseEnter={() => setHl(g)} onMouseLeave={() => setHl(null)} style={{ cursor: 'pointer' }}>
                  <rect x={0} y={b - rowH + 6} width={Wd} height={rowH} fill="transparent" />
                  <path d={pathS(rr.dens[g], b)} fill={REG_COL[g]} opacity={on ? 0.8 : 0.22} />
                  <path d={lineS(rr.dens[g], b, amp)} fill="none" stroke="#e6e9ee" strokeWidth="1.1" opacity={on ? 0.9 : 0.3} />
                  <text x={m.l - 8} y={b - 16} textAnchor="end" className="tl-marklabel" fill={on ? '#fff' : '#8b929b'}>{g}</text>
                  <text x={m.l - 8} y={b - 2} textAnchor="end" className="tl-tick">{rr.n[g].toLocaleString()} books</text>
                </g>
              );
            })}
            <line x1={m.l} x2={Wd - m.r} y1={Hs - m.b} y2={Hs - m.b} className="tl-grid" />
            <g transform={`translate(0 ${Hs - m.b + 16})`}>{ticks}</g>
          </svg>
        </div>
      </div>
      <h3 style={{ marginTop: 14 }}>The four ridges together</h3>
      <div className="tl-legend" style={{ display: 'flex', flexWrap: 'wrap', gap: '4px 16px', fontSize: 12, margin: '4px 0' }}>
        {REG.map((g) => <span key={g} onMouseEnter={() => setHl(g)} onMouseLeave={() => setHl(null)} style={{ cursor: 'pointer', opacity: !hl || hl === g ? 1 : 0.4 }}><span style={{ display: 'inline-block', width: 16, height: 0, borderTop: `3px solid ${REG_COL[g]}`, marginRight: 6, verticalAlign: 'middle' }} />{g} ({rr.n[g].toLocaleString()} books)</span>)}
      </div>
      <svg viewBox={`0 0 ${Wd} ${Ho}`} className="tl-hist" role="img" aria-label="The four regional ridges on one plot">
        {[1, 2, 3, 4, 5, 6].map((b) => <line key={b} x1={sxo(b)} x2={sxo(b)} y1={mo.t} y2={Ho - mo.b} stroke="#7d8794" opacity="0.35" />)}
        {REG.map((g) => <path key={`a${g}`} d={areaO(rr.dens[g])} fill={REG_COL[g]} opacity={!hl || hl === g ? 0.16 : 0.04} />)}
        {REG.map((g) => <path key={g} d={lineO(rr.dens[g])} fill="none" stroke={REG_COL[g]} strokeWidth={hl === g ? 3.4 : 2.4} opacity={!hl || hl === g ? 1 : 0.25} onMouseEnter={() => setHl(g)} onMouseLeave={() => setHl(null)} />)}
        <line x1={mo.l} x2={Wd - mo.r} y1={Ho - mo.b} y2={Ho - mo.b} className="tl-grid" />
        <g transform={`translate(0 ${Ho - mo.b + 16})`}>{ERA_SHORT.map((t, i) => <text key={t} x={sxo(i + 0.5)} textAnchor="middle" className="tl-tick">{t}</text>)}</g>
      </svg>
      <p className="tl-note">Each curve adds up to 1, so heights compare each region's own timing and not the number of books.</p>
      <table className="tl-table">
        <thead><tr><th>Region</th><th>Books</th>{ERA_SHORT.map((t) => <th key={t}>{t}</th>)}</tr></thead>
        <tbody>
          {REG.map((g) => <tr key={g} style={{ opacity: !hl || hl === g ? 1 : 0.45 }} onMouseEnter={() => setHl(g)} onMouseLeave={() => setHl(null)}><td><span style={{ display: 'inline-block', width: 10, height: 10, background: REG_COL[g], borderRadius: 2, marginRight: 6 }} />{g}</td><td>{rr.n[g].toLocaleString()}</td>{rr.shares[g].map((v, i) => <td key={i}>{v.toFixed(0)}%</td>)}</tr>)}
        </tbody>
      </table>
      <p className="tl-note">Share of each region's place mentions that lie in each era. All four regions peak in 1800–1917. The west is almost entirely before 1945. The east and south have a second peak from 1991 on, and the south alone has a peak before 1400.</p>
    </Panel>
  );
}

const DIR_COL = { 'New York': '#e0a526', Toronto: '#d96bb0', Moscow: C.orange, Warsaw: C.blue, neither: '#7b8088', round: '#2a313b' };
const DIR_TEXT = { 'New York': 'leans towards New York', Toronto: 'leans towards Toronto', Moscow: 'leans towards Moscow', Warsaw: 'leans towards Warsaw', neither: 'elongated, towards neither', round: 'nearly round, no direction' };
const SHORT = { 'Soviet Union': 'USSR', 'Russia (Federation)': 'Russia', 'Muscovy (Grand Duchy)': 'Muscovy', 'Kievan Rus': 'Kyiv Rus', 'Zaporozhian Sich': 'Sich', 'Donbas (Region)': 'Donbas', 'Crimean Khanate': 'Crim. Khanate' };
const shortName = (n) => SHORT[n] || (n.length > 12 ? n.slice(0, 11) + '…' : n);

function DirectionByPeriod({ map }) {
  const [data, setData] = useState(null);
  const [per, setPer] = useState('1991+');
  const [show, setShow] = useState('core');
  const [tip, setTip] = useState(null);
  const [selOv, setSelOv] = useState(null);
  const [pool, setPool] = useState(null);
  const [poolPub, setPoolPub] = useState(null);
  const [pw, setPw] = useState('subject');
  useEffect(() => {
    let off = false;
    fetch(`${process.env.PUBLIC_URL}/data/tests_lab.json`).then((r) => r.json()).then((x) => { if (!off) { setPool(x.compact.theme.pool.filter((p) => p[4] !== 1).map((p) => [p[0], p[1], p[2]])); if (x.compact.theme_pub) setPoolPub(x.compact.theme_pub.pool.map((p) => [p[0], p[1], p[2]])); } }).catch(() => {});
    return () => { off = true; };
  }, []);
  useEffect(() => {
    let off = false;
    fetch(`${process.env.PUBLIC_URL}/data/direction_by_period.json`).then((r) => r.json()).then((d) => { if (!off) setData(d); }).catch(() => {});
    return () => { off = true; };
  }, []);
  const rows = React.useMemo(() => {
    if (!data) return [];
    const all = Object.entries(data.cells).map(([name, cs]) => {
      const q = data.eras.filter((e) => cs[e]);
      return { name, cs, q: q.length, mos: q.filter((e) => cs[e].lc === 'Moscow').length, books: q.reduce((s, e) => s + cs[e].n, 0) };
    });
    const f = show === 'all' ? all : show === 'moscow' ? all.filter((r) => r.mos >= 1) : all.filter((r) => r.q >= 4 && r.mos >= 2);
    return f.sort((a, b) => b.books - a.books);
  }, [data, show]);
  if (!data) return null;
  const move = (e, d, era, name) => setTip({ x: e.clientX, y: e.clientY, d, era, name });
  return (
    <Panel n="2" title="How does the direction of a heading's oval change from period to period?"
      lead="Each cell is the oval of the books under one subject heading whose place entries refer to one period. Colour is the direction of its long axis (within 22.5° of the bearing from the oval's centre to Moscow or Warsaw), the label is the place that the most books name, then how many times as long as wide the oval is and how many books there are. Hover a cell for its details.">
      <div className="tl-toolbar">
        <label>Headings <select value={show} onChange={(e) => setShow(e.target.value)}>
          <option value="core">With at least four periods and two towards Moscow</option>
          <option value="moscow">Towards Moscow in at least one period</option>
          <option value="all">All that can be drawn in at least one period</option>
        </select></label>
        <span className="tl-muted">{rows.length} headings</span>
      </div>
      <div className="tl-tablewrap" style={{ maxHeight: 520, maxWidth: '100%' }}>
        <table className="tl-table" style={{ borderCollapse: 'separate', borderSpacing: 2 }}>
          <thead><tr><th style={{ position: 'sticky', left: 0, background: 'var(--surface-1, #0d1117)' }}>Subject heading</th>{data.eras.map((e) => <th key={e} style={{ textAlign: 'center' }}>{LABEL[e]}</th>)}</tr></thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r.name}>
                <td style={{ position: 'sticky', left: 0, background: 'var(--surface-1, #0d1117)', whiteSpace: 'nowrap', paddingRight: 12 }}>{r.name}</td>
                {data.eras.map((e) => {
                  const d = r.cs[e];
                  if (!d) return <td key={e} style={{ minWidth: 92, border: '1px solid #232a33' }} />;
                  const light = d.lc === 'Moscow' || d.lc === 'Warsaw';
                  return (
                    <td key={e} tabIndex={0} onMouseEnter={(ev) => move(ev, d, e, r.name)} onMouseMove={(ev) => move(ev, d, e, r.name)} onMouseLeave={() => setTip(null)}
                      onFocus={(ev) => { const b = ev.currentTarget.getBoundingClientRect(); setTip({ x: b.left + 10, y: b.bottom, d, era: e, name: r.name }); }} onBlur={() => setTip(null)}
                      style={{ minWidth: 92, textAlign: 'center', background: DIR_COL[d.lc], color: light ? '#fff' : '#d6d9de', borderRadius: 3, padding: '3px 4px', lineHeight: 1.25, cursor: 'default' }}>
                      <div style={{ fontWeight: 600, fontSize: 12 }}>{shortName(d.top[0])}</div>
                      <div style={{ fontSize: 10.5, opacity: 0.9 }}>{d.el}× · {d.n.toLocaleString()} books</div>
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="tl-legend" style={{ display: 'flex', flexWrap: 'wrap', gap: '6px 16px', fontSize: 12, margin: '10px 0' }}>
        {Object.keys(DIR_COL).map((k) => <span key={k}><span style={{ display: 'inline-block', width: 11, height: 11, background: DIR_COL[k], borderRadius: 2, marginRight: 6, verticalAlign: '-1px' }} />{DIR_TEXT[k]}</span>)}
        <span><span style={{ display: 'inline-block', width: 11, height: 11, border: '1px solid #232a33', borderRadius: 2, marginRight: 6, verticalAlign: '-1px' }} />fewer than 8 books or 6 places</span>
      </div>
      {map && (() => {
        const ov = [];
        const isPub = pw === 'pub';
        Object.entries(data.cells).forEach(([name, cs]) => { const d = cs[per]; if (d && (!isPub || (d.po && d.pp))) ov.push({ name, d }); });
        ov.sort((a, b) => b.d.n - a.d.n);
        const rad = Math.PI / 180;
        const brgTo = (a, b, c, e) => { const y = Math.sin((e - b) * rad) * Math.cos(c * rad); const x = Math.cos(a * rad) * Math.sin(c * rad) - Math.sin(a * rad) * Math.cos(c * rad) * Math.cos((e - b) * rad); return (Math.atan2(y, x) / rad + 360) % 360; };
        const adf = (x, y) => { const q = Math.abs(x - y) % 180; return Math.min(q, 180 - q); };
        const pubClass = (po) => { if (po[5] < 1.5) return 'round'; const dm = adf(po[4], brgTo(po[0], po[1], 40.71, -74.01)), dw = adf(po[4], brgTo(po[0], po[1], 43.65, -79.38)); return Math.min(dm, dw) > 22.5 ? 'neither' : dm < dw ? 'New York' : 'Toronto'; };
        const ovals = ov.map(({ name, d }) => {
          const lc = isPub ? pubClass(d.po) : d.lc;
          const o = isPub ? { lat: d.po[0], lon: d.po[1], ra: d.po[2], rb: d.po[3], bearing: d.po[4], el: d.po[5] } : { lat: d.oval[0], lon: d.oval[1], ra: d.oval[2], rb: d.oval[3], bearing: d.b, el: d.el };
          return {
            az: isPub, id: name, label: `${name}, ${LABEL[per]}`, lat: o.lat, lon: o.lon, ra: o.ra, rb: o.rb, bearing: o.bearing, solid: lc !== 'round', color: DIR_COL[lc === 'round' ? 'neither' : lc] === '#7b8088' ? '#aab1bb' : DIR_COL[lc], d: { ...d, lc, el: o.el, b: Math.round(o.bearing) },
            pts: (isPub ? d.pp : (d.pts || [])).map((p) => [p[0], p[1], p[2], p[3]]),
            facts: [isPub
              ? `${d.n.toLocaleString()} books under the heading in this period, of which ${(d.mp ?? 0).toLocaleString()} have a publication place that is on the map (${d.pp.length} places in all). ${DIR_TEXT[lc][0].toUpperCase()}${DIR_TEXT[lc].slice(1)}${o.el < 1.5 ? ' (too round for the direction to count)' : ''}. These are places of publication, not places the books are about.`
              : `${d.n.toLocaleString()} books under the heading in this period, of which ${d.m != null ? d.m.toLocaleString() : '?'} name a place that is on the map (${d.k} places in all). ${DIR_TEXT[lc][0].toUpperCase()}${DIR_TEXT[lc].slice(1)}${d.el < 1.5 ? ' (too round for the direction to count)' : ''}. Most named: ${d.top.join('; ')}.`],
          };
        });
        const T = data.tests[per];
        const row = (lab, t) => t && <tr key={lab}><td>{lab}</td><td><b>{t[0]}</b></td><td>{t[1]}</td><td>{t[2] < 0.01 ? t[2].toFixed(3) : t[2].toFixed(2)}</td></tr>;
        const cur = ov.find((q) => q.name === selOv);
        return (
          <div style={{ marginTop: 14 }}>
            <h3>The ovals of the period</h3>
            {data.cells && poolPub && (
              <div className="tl-toolbar" style={{ marginBottom: 8 }}>
                <label>Which places? <select value={pw} onChange={(e) => { setPw(e.target.value); setSelOv(null); }}>
                  <option value="subject">Places the books are about</option>
                  <option value="pub">Places where the books were published</option>
                </select></label>
                {isPub && <span className="tl-muted">Ovals of publication places (imprints) of the same books, fitted on an equidistant projection (curved when long). Not mixed with subject places. The counts table below is for subject places.</span>}
              </div>
            )}
            <div className="tl-btns" style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 8 }}>
              {data.eras.map((e) => <button key={e} type="button" onClick={() => setPer(e)} aria-pressed={per === e} style={{ fontWeight: per === e ? 700 : 400, outline: per === e ? '2px solid #7fb3ff' : 'none' }}>{LABEL[e]}</button>)}
            </div>
            <OvalMap key={pw} fitCities={isPub} ovals={ovals} sel={cur ? selOv : null} setSel={setSelOv} ukraine={map.outline} pool={isPub ? poolPub : pool} unit={isPub ? 'books' : 'book mentions'} startView={isPub ? 'world' : undefined}
              onHover={(ev, o) => (ev && !cur ? move(ev, o.d, per, o.id) : setTip(null))}
              cities={[{ name: 'Moscow', lat: 55.75, lon: 37.62, color: C.orange }, { name: 'Warsaw', lat: 52.23, lon: 21.01, color: C.blue }, { name: 'Istanbul', lat: 41.01, lon: 28.98, color: '#2bb3a3' }, ...(isPub ? NA_CITIES : [])]}
              legend={<>{isPub ? <><span><i style={{ background: DIR_COL['New York'] }} />towards New York</span><span><i style={{ background: DIR_COL.Toronto }} />towards Toronto</span></> : <><span><i style={{ background: C.orange }} />towards Moscow</span><span><i style={{ background: C.blue }} />towards Warsaw</span></>}<span><i style={{ background: '#aab1bb' }} />towards neither</span><span><i style={{ background: 'transparent', border: '1px solid #8b929b' }} />nearly round (dashed, faint)</span></>}
              extra={cur && cur.d.pub ? <p style={{ margin: '6px 0 0' }}>Published {cur.d.pub[0]}–{cur.d.pub[4]}, median {cur.d.pub[2]}: {cur.d.pub[5]}% before 1991, {cur.d.pub[6]}% 1991–2013, {cur.d.pub[7]}% from 2014 ({cur.d.pub[8]} books with a date).</p> : null} />
            <p className="tl-note">One oval for each heading with at least 8 books and 6 places in the period: solid where the oval is at least 1.5 times as long as wide (orange towards Moscow, blue towards Warsaw, grey towards neither), dashed and faint where it is nearly round. The map shows Europe, Turkey and western Russia so whole ovals are visible. In the publication view the colours show which of New York and Toronto the long axis lies nearer, within 22.5°; the two cities are only about 5° apart as seen from Europe, so do not read much into a difference between them. Dashed, faint ovals are less than 1.5 times as long as wide, so they have no meaningful long axis and no direction (most imprints of such headings lie in Ukraine and its neighbours). Publication ovals are fitted and drawn on an equidistant projection, so long ones curve across the Atlantic. Hover an oval for its heading; click one to zoom to it, see its long axis and angle from north, the places that drew it (dots, sized by the number of books naming them) and how much of it lies in Ukraine.</p>
            <div className="tl-readout" style={{ maxWidth: 760 }}>
              <h3>{LABEL[per]}</h3>
              {isPub ? <p className="tl-muted">The counts against random place sets are made for subject places. For places of publication, compare the ovals by eye or select one to see its dots and coverage.</p> : T ? (<>
                <p><b>{T.elong}</b> of the {ov.length} headings drawn here are elongated enough to have a direction. Counted against random place sets of the same period and sizes:</p>
                <table className="tl-table"><thead><tr><th>Towards</th><th>Observed</th><th>Expected</th><th>p</th></tr></thead><tbody>{row('Moscow (nearer of Moscow and Istanbul)', T.moscow)}{row('Istanbul (nearer)', T.istanbul)}{row('Warsaw', T.warsaw)}</tbody></table>
                <p className="tl-note">The test is on the counts. No single oval is significant on its own after correcting for the number of headings, so the ovals drawn are those that make up the counts, not individually significant ones.</p>
              </>) : <p className="tl-muted">Too few headings in this period have enough books and places for a direction count to be meaningful.</p>}
            </div>
          </div>
        );
      })()}
      <p className="tl-note">The book count is every book under the heading in that period, whether or not it names a located place; the oval is drawn from the places of those that do, weighted by the number of books naming each. These are descriptive comparisons on small numbers of books and are not tested against random place sets. The tested counts are in the paper.</p>
      {tip && (
        <div role="tooltip" style={{ position: 'fixed', left: Math.min(tip.x + 14, window.innerWidth - 300), top: Math.min(tip.y + 14, window.innerHeight - 260), width: 300, background: '#161b22', color: '#e6e9ee', border: '1px solid #3a424d', borderRadius: 8, padding: '9px 11px', fontSize: 12, lineHeight: 1.4, boxShadow: '0 6px 20px rgba(0,0,0,.45)', pointerEvents: 'none', zIndex: 50 }}>
          <div style={{ fontWeight: 700, marginBottom: 2 }}>{tip.name}, {LABEL[tip.era]}</div>
          <div style={{ color: DIR_COL[tip.d.lc] === '#2a313b' ? '#aab1bb' : DIR_COL[tip.d.lc] }}>{DIR_TEXT[tip.d.lc]}</div>
          <div>{tip.d.n.toLocaleString()} books in the period, {tip.d.m != null ? `${tip.d.m.toLocaleString()} on the map` : ''}, {tip.d.k} places; oval {tip.d.el}× as long as wide, long axis {tip.d.b}° from north{tip.d.el < 1.5 ? ' (too round for the direction to count)' : ''}.</div>
          {tip.d.pub && (
            <div style={{ marginTop: 6 }}>
              Published {tip.d.pub[0]}–{tip.d.pub[4]}, median {tip.d.pub[2]} (middle half {tip.d.pub[1]}–{tip.d.pub[3]}; {tip.d.pub[8]} books with a date).
              <div style={{ display: 'flex', height: 8, borderRadius: 4, overflow: 'hidden', margin: '5px 0 2px', background: '#2a313b' }} aria-hidden="true">
                <div style={{ width: `${tip.d.pub[5]}%`, background: '#d0c2f0' }} />
                <div style={{ width: `${tip.d.pub[6]}%`, background: '#9573d9' }} />
                <div style={{ width: `${tip.d.pub[7]}%`, background: '#5a34a8' }} />
              </div>
              <span style={{ color: '#aab1bb' }}><span style={{ display: 'inline-block', width: 9, height: 9, borderRadius: 2, background: '#d0c2f0', margin: '0 4px 0 0', verticalAlign: '-1px' }} />{tip.d.pub[5]}% published before 1991 · <span style={{ display: 'inline-block', width: 9, height: 9, borderRadius: 2, background: '#9573d9', margin: '0 4px 0 0', verticalAlign: '-1px' }} />{tip.d.pub[6]}% 1991–2013 · <span style={{ display: 'inline-block', width: 9, height: 9, borderRadius: 2, background: '#5a34a8', margin: '0 4px 0 0', verticalAlign: '-1px' }} />{tip.d.pub[7]}% 2014 on</span>
            </div>
          )}
          <div style={{ marginTop: 4 }}>Most named: {tip.d.top.join('; ')}.</div>
        </div>
      )}
    </Panel>
  );
}

function RidgeLines({ grid, series, unit, ticks }) {
  const W = 420, H = 150, m = { l: 8, r: 8, t: 8, b: 26 };
  const gmin = grid[0], gmax = grid[grid.length - 1];
  const peak = Math.max(...series.flatMap((s) => s.y));
  const sx = (v) => m.l + ((v - gmin) / (gmax - gmin)) * (W - m.l - m.r);
  const sy = (v) => H - m.b - (v / peak) * (H - m.b - m.t);
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="tl-hist" role="img" aria-label={`Footprint by ${unit}`}>
      <line x1={m.l} x2={W - m.r} y1={H - m.b} y2={H - m.b} stroke="#7d8794" />
      {ticks.map((t) => <g key={t}><line x1={sx(t)} x2={sx(t)} y1={H - m.b} y2={H - m.b + 4} stroke="#7d8794" /><text x={sx(t)} y={H - 8} className="tl-tick" textAnchor="middle">{t}{unit}</text></g>)}
      {series.map((s) => <path key={s.name} d={s.y.map((y, k) => `${k ? 'L' : 'M'} ${sx(grid[k]).toFixed(1)} ${sy(y).toFixed(1)}`).join(' ')} fill="none" stroke={s.color} strokeWidth={s.w || 1.8} strokeDasharray={s.dash} />)}
    </svg>
  );
}

function SelectionCheck({ map }) {
  const [d, setD] = useState(null);
  useEffect(() => {
    let off = false;
    fetch(`${process.env.PUBLIC_URL}/data/selection_check.json`).then((r) => r.json()).then((x) => { if (!off) setD(x); }).catch(() => {});
    return () => { off = true; };
  }, []);
  if (!d || !map) return null;
  const k = Math.cos((48.5 * Math.PI) / 180);
  const x0 = 22 * k, x1 = 40.5 * k, y0 = 44, y1 = 52.5;
  const W = 640, H = Math.round((W * (y1 - y0)) / (x1 - x0));
  const sx = (lon) => ((lon * k - x0) / (x1 - x0)) * W;
  const sy = (lat) => H - ((lat - y0) / (y1 - y0)) * H;
  const ring = (r) => 'M ' + r.map(([la, lo]) => `${sx(lo).toFixed(1)} ${sy(la).toFixed(1)}`).join(' L ') + ' Z';
  const area = (w) => 2.5 + Math.sqrt(w) * 3.4;
  const names = { all: 'All books', dated: 'With a period', undated: 'Without a period' };
  const colors = { all: C.white, dated: C.orange, undated: C.blue };
  const mk = (axis) => ['all', 'dated', 'undated'].map((n) => ({ name: n, y: d.ridges[n][axis], color: colors[n], w: n === 'all' ? 2.4 : 1.7, dash: n === 'all' ? '5 4' : undefined }));
  const S = d.sets;
  const reg = (n, r) => `${Math.round(S[n].regions[r] || 0)}%`;
  return (
    <Panel n="3" title="Are the books with a period a biased sample?"
      lead="The period ridges use only the books whose subject headings carry a date. Most books that name a located place do not, so this panel compares the footprint of the books with a period to that of the books without one, and shows all of them together with no period needed.">
      <div className="tl-row">
        <div className="tl-col" style={{ flex: '1 1 380px', minWidth: 0, maxWidth: 640 }}>
          <h3>All {S.all.n.toLocaleString()} books that name a located place</h3>
          <svg viewBox={`0 0 ${W} ${H}`} className="tl-hist" role="img" aria-label="Places named by all located books, no period needed">
            {map.outline.map((r, i) => <path key={i} d={ring(r)} fill="#1a2029" stroke="#7d8794" strokeWidth="1" />)}
            <polyline points={map.river.map(([la, lo]) => `${sx(lo)},${sy(la)}`).join(' ')} fill="none" stroke="#6aa6d8" strokeWidth="2" opacity="0.7" />
            {d.points.map(([la, lo, w], i) => <circle key={i} cx={sx(lo)} cy={sy(la)} r={area(w)} fill={C.orange} opacity="0.5" stroke="#fff" strokeWidth="0.4"><title>{`${w.toFixed(1)} books`}</title></circle>)}
          </svg>
          <p className="tl-note">Each circle is a place; its area shows how many books name it (a book with k places gives each 1/k). The blue line is the Dnipro.</p>
        </div>
        <div className="tl-col" style={{ flex: '1 1 320px' }}>
          <h3>West to east</h3>
          <RidgeLines grid={d.lon} series={mk('lon')} unit="°E" ticks={[22, 25, 28, 31, 34, 37, 40]} />
          <h3>South to north</h3>
          <RidgeLines grid={d.lat} series={mk('lat')} unit="°N" ticks={[44, 46, 48, 50, 52]} />
          <div className="tl-legend" style={{ display: 'flex', flexWrap: 'wrap', gap: '4px 14px', fontSize: 12, margin: '6px 0' }}>
            {['all', 'dated', 'undated'].map((n) => <span key={n}><span style={{ display: 'inline-block', width: 16, height: 0, borderTop: `3px ${n === 'all' ? 'dashed' : 'solid'} ${colors[n]}`, marginRight: 6, verticalAlign: 'middle' }} />{names[n]} ({S[n].n.toLocaleString()})</span>)}
          </div>
        </div>
      </div>
      <table className="tl-table">
        <thead><tr><th /><th>Books</th><th>Mean position</th><th>West</th><th>Centre</th><th>East</th><th>South</th><th>Crimea</th></tr></thead>
        <tbody>
          {['all', 'dated', 'undated'].map((n) => (
            <tr key={n}><td>{names[n]}</td><td>{S[n].n.toLocaleString()}</td><td>{S[n].lon.toFixed(1)}°E, {S[n].lat.toFixed(1)}°N</td><td>{reg(n, 'west')}</td><td>{reg(n, 'centre')}</td><td>{reg(n, 'east')}</td><td>{reg(n, 'south')}</td><td>{Math.round(S[n].crimea)}%</td></tr>
          ))}
        </tbody>
      </table>
      <p>Divergence between the books with a period and those without: <b>{d.test.lon.jsd.toFixed(3)}</b> bits from west to east (<b>{d.test.lon.null.toFixed(3)}</b> expected if books were assigned to the two groups at random, p = {d.test.lon.p.toFixed(3)}) and <b>{d.test.lat.jsd.toFixed(3)}</b> bits from south to north ({d.test.lat.null.toFixed(3)} expected, p = {d.test.lat.p.toFixed(3)}).</p>
      <p className="tl-note">The two groups are almost the same. The divergence is detectable with so many books but small beside the 1 bit of a complete separation, so the books with a period are not a biased sample of where the books are about.</p>
    </Panel>
  );
}


function PublicationByYear({ map }) {
  const [rows, setRows] = useState(null);
  const [pool, setPool] = useState(null);
  const [sel, setSel] = useState(null);
  useEffect(() => {
    let off = false;
    fetch(`${process.env.PUBLIC_URL}/data/pub_by_year.json`).then((r) => r.json()).then((d) => { if (!off) setRows(d); }).catch(() => {});
    fetch(`${process.env.PUBLIC_URL}/data/tests_lab.json`).then((r) => r.json()).then((x) => { if (!off && x.compact.theme_pub) setPool(x.compact.theme_pub.pool.map((p) => [p[0], p[1], p[2]])); }).catch(() => {});
    return () => { off = true; };
  }, []);
  if (!rows || !map) return null;
  const COLS = ['#a78bfa', C.blue, C.orange, '#2bb3a3'];
  const REG = ['Ukraine', 'Russia', 'Poland', 'USA and Canada', 'Other countries'];
  const ovals = rows.map((r, i) => ({
    az: true, id: r.name, label: `Published ${r.name}`, lat: r.oval[0], lon: r.oval[1], ra: r.oval[2], rb: r.oval[3], bearing: r.oval[4], solid: r.oval[5] >= 1.5, color: COLS[i],
    pts: r.pts, facts: [`${r.mapped.toLocaleString()} of ${r.books.toLocaleString()} books published ${r.name} have a publication place on the map (${r.k} places). Oval ${r.oval[5]}× as long as wide. ${r.regions.Ukraine}% of these books were published in Ukraine and ${r.regions['USA and Canada']}% in the United States or Canada.`],
  }));
  return (
    <Panel n="3" title="Where were the books published, by year of publication?"
      lead="Each oval is drawn from the places of publication (the imprint) of all books published in one period, whatever the book is about. A book with several publication places counts once at each place. Publication places and subject places are never mixed. Because these ovals can span the Atlantic, they are fitted and drawn on an equidistant map projection, so a long oval is curved like a great-circle route.">
      <OvalMap fitCities ovals={ovals} sel={sel} setSel={setSel} ukraine={map.outline} pool={pool} unit="books" startView="world" cities={[{ name: 'Moscow', lat: 55.75, lon: 37.62, color: C.orange }, { name: 'Warsaw', lat: 52.23, lon: 21.01, color: C.blue }, ...NA_CITIES]}
        legend={<>{rows.map((r, i) => <span key={r.name}><i style={{ background: COLS[i] }} />{r.name}</span>)}</>} />
      <div className="tl-tablewrap" style={{ marginTop: 10 }}>
        <table className="tl-table">
          <thead><tr><th>Published</th><th>Books</th><th>With a place on the map</th>{REG.map((g) => <th key={g}>{g}</th>)}<th>Oval centre</th><th>Long ÷ short</th></tr></thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r.name} onClick={() => setSel(sel === r.name ? null : r.name)} style={{ cursor: 'pointer', background: sel === r.name ? '#1f2a38' : undefined }}>
                <td>{r.name}</td><td>{r.books.toLocaleString()}</td><td>{r.mapped.toLocaleString()}</td>
                {REG.map((g) => <td key={g}>{Math.round(r.regions[g] || 0)}%</td>)}
                <td>{r.oval[1].toFixed(1)}°E, {r.oval[0].toFixed(1)}°N</td><td>{r.oval[5]}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p className="tl-note">Shares are the percentage of the books with a mapped publication place that have at least one imprint in the country, so they can add to more than 100%. Before 1945 the books come from Ukraine, Poland, Russia and western Europe. Between 1945 and 1990 many were published in the diaspora, which stretches the oval from Europe to North America. After 1991 most are published in Ukraine and the oval is nearly round and centred near Kyiv. Solid ovals are at least 1.5 times as long as wide; a dashed oval is nearly round and has no meaningful long axis. The ovals are fitted and drawn on an equidistant projection, so a long one curves across the Atlantic. Click a row or an oval to see its places as dots. Books without a year of publication are left out.</p>
    </Panel>
  );
}

export default function DriftLab() {
  const [data, setData] = useState(null);
  const [map, setMap] = useState(null);
  const [error, setError] = useState(null);
  useEffect(() => {
    let off = false;
    fetch(`${process.env.PUBLIC_URL}/data/region_ridge.json`).then((r) => r.json()).then((d) => { if (!off) setData(d); }).catch((e) => { console.error(e); if (!off) setError(e); });
    fetch(`${process.env.PUBLIC_URL}/data/ridge_map.json`).then((r) => r.json()).then((d) => { if (!off) setMap(d); }).catch((e) => console.error(e));
    return () => { off = true; };
  }, []);
  return (
    <div className="tl-root">
      <p className="tl-back"><Link to="/tests-lab">← Tests lab</Link></p>
      <h1>Drift lab: which regions and eras do the books cover?</h1>
      <p className="tl-sub">Drift here means that the part of the country the books are about changes from one period to the next. The ridges here show when the books about each of four regions are about, and the panels below show how the direction of a heading's oval changes over time.</p>
      {error && <p className="tl-err">The data file could not be loaded.</p>}
      {!data && !error && <p className="tl-muted">Loading…</p>}
      {data && map && <RegionRidges rr={data} map={map} />}
      {data && <DirectionByPeriod map={map} />}
      {data && <PublicationByYear map={map} />}
      {data && <SelectionCheck map={map} />}
    </div>
  );
}
