import React from 'react';
import { HashRouter, Routes, Route, useLocation } from 'react-router-dom';
import SiteNav from './SiteNav';
import Landing from './pages/Landing';
import TemporalMap from './pages/TemporalMap';
import TopicsRiver from './pages/TopicsRiver';
import InfluenceRiver from './pages/InfluenceRiver';
import Lag from './pages/Lag';
import LagLanguages from './pages/LagLanguages';
import PlaceClusters from './pages/PlaceClusters';
import TestsLab from './pages/TestsLab';
import DriftLab from './pages/DriftLab';
import CatalogLab from './pages/CatalogLab';
import HomogeneityMap from './pages/HomogeneityMap';
import Subjects3D from './pages/Subjects3D';

// HashRouter (not BrowserRouter) is used deliberately: GitHub Pages serves
// static files with no server-side rewrite rules, so a deep link or a
// browser refresh on e.g. /map would 404 under BrowserRouter's clean URLs.
// Hash-based routes (/#/map) always resolve to index.html first, then the
// router reads the hash client-side -- no server config needed.
// The site bar is a flex row above the page, not an overlay, so no page's
// own controls are covered. The landing page keeps its own top bar.
function Shell() {
  const { pathname } = useLocation();
  const home = pathname === '/';
  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
      {!home && <SiteNav />}
      <div style={{ flex: '1 1 auto', minHeight: 0, overflow: 'auto', position: 'relative' }}>
        <Pages />
      </div>
    </div>
  );
}

function Pages() {
  return (
      <Routes>
        <Route path="/" element={<Landing />} />
        <Route path="/map" element={<TemporalMap />} />
        <Route path="/topics" element={<TopicsRiver />} />
        <Route path="/influence" element={<InfluenceRiver />} />
        <Route path="/lag" element={<Lag />} />
        <Route path="/lag-languages" element={<LagLanguages />} />
        <Route path="/place-map" element={<PlaceClusters />} />
          <Route path="/tests-lab" element={<TestsLab />} />
          <Route path="/drift-lab" element={<DriftLab />} />
          <Route path="/catalog-lab" element={<CatalogLab />} />
          <Route path="/homogeneity" element={<HomogeneityMap />} />
          <Route path="/subjects-3d" element={<Subjects3D />} />
      </Routes>
  );
}

export default function App() {
  return (
    <HashRouter>
      <Shell />
    </HashRouter>
  );
}
