  '/tests-lab': {
    scope: 'Each test uses only the records that name a drawable place in the region(s) it compares; records that name only the country are not used. The number of records is given beside each test.',
    rel: [['/drift-lab', 'Drift lab'], ['/catalog-lab', 'Catalog lab'], ['/homogeneity', 'Homogeneity map']] },
  '/drift-lab': {
    stat: ['1,560', 'books used'],
    scope: 'The regional ridges use 1,560 books that have an era and a located place; a book about places in two regions counts in both, each place weighing 1/k. Books with no dated period or no located place are not used.',
    rel: [['/tests-lab', 'Tests lab'], ['/subjects-3d', '3D relief'], ['/catalog-lab', 'Catalog lab']] },
